// Merge generic area card translations
Object.keys(genericAreaCardTranslations).forEach((lang) => {
  Object.assign(translations[lang as Language], genericAreaCardTranslations[lang as Language]);
});

// Merge studio translations
Object.keys(studioTranslations).forEach((lang) => {
  Object.assign(translations[lang as Language], studioTranslations[lang as Language]);
});

// Merge kitchen translations
Object.keys(kitchenTranslations).forEach((lang) => {
  Object.assign(translations[lang as Language], kitchenTranslations[lang as Language]);
});


export function t(lang: Language, key: string, params: Record<string, string> = {}): string {
  let text = translations[lang]?.[key] || translations['en'][key] || key;
  Object.entries(params).forEach(([k, v]) => {
    text = text.replace(`{${k}}`, v);
  });
  return text;
}

export function getLocale(lang: Language): string {
  return lang === 'en' ? 'en-US' : lang === 'es' ? 'es-MX' : 'zh-CN';
}

export function getOfferDate(lang: Language): string {
  const date = new Date();
  date.setDate(date.getDate() + 5);
  return date.toLocaleDateString(getLocale(lang), { month: 'short', day: 'numeric' });
}
